mapper.select:
select
c1.C_Name as metUnitName,
c1.C_Abbreviation as metUnitAbbName,
mn.*
from  Me_Type_Library mn
left join  SYS_Company c1 on mn.Met_Unit=c1.C_Id

    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.Met_Parent_Id = #{params.metParentId}
    
    
        and mn.Met_State = #{params.metState}
    
    
        and mn.Met_Name like concat('%',#{params.metName},'%')
    
    
        and mn.Met_Code like concat('%',#{params.metCode},'%')
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Met_Create_Time desc
